"use strict";(self.webpackChunkdammy=self.webpackChunkdammy||[]).push([[988],{2485:(n,e,s)=>{s.r(e),s.d(e,{data:()=>a});const a={key:"v-d0736a32",path:"/usage/",title:"Usage",lang:"en-US",frontmatter:{},excerpt:"",headers:[{level:2,title:"Basic usage",slug:"basic-usage",children:[]},{level:2,title:"File generation",slug:"file-generation",children:[{level:3,title:"Number of files",slug:"number-of-files",children:[]},{level:3,title:"File extension",slug:"file-extension",children:[]}]},{level:2,title:"Image file generation",slug:"image-file-generation",children:[{level:3,title:"Image size",slug:"image-size",children:[]}]},{level:2,title:"File name options",slug:"file-name-options",children:[{level:3,title:"No symbols",slug:"no-symbols",children:[]},{level:3,title:"Include whitespace",slug:"include-whitespace",children:[]},{level:3,title:"Include 2-byte characters",slug:"include-2-byte-characters",children:[]}]},{level:2,title:"Directory generation",slug:"directory-generation",children:[{level:3,title:"Multiple directories",slug:"multiple-directories",children:[]},{level:3,title:"Create files in every intermediate directory",slug:"create-files-in-every-intermediate-directory",children:[]}]},{level:2,title:"Shell brace expansion",slug:"shell-brace-expansion",children:[]},{level:2,title:"Cold run",slug:"cold-run",children:[]},{level:2,title:"Options reference",slug:"options-reference",children:[]}],filePathRelative:"usage/README.md",git:{updatedTime:1779339153e3,contributors:[{name:"ontheroadjp",email:"dev@ontheroad.jp",commits:2}]}}},3199:(n,e,s)=>{s.r(e),s.d(e,{default:()=>l});const a=(0,s(6252).uE)('<h1 id="usage" tabindex="-1"><a class="header-anchor" href="#usage" aria-hidden="true">#</a> Usage</h1><h2 id="basic-usage" tabindex="-1"><a class="header-anchor" href="#basic-usage" aria-hidden="true">#</a> Basic usage</h2><p>Running <code>dammy.sh</code> with no arguments creates a single dummy <code>.txt</code> file in the current directory.</p><div class="language-bash ext-sh line-numbers-mode"><pre class="language-bash"><code>$ dammy.sh\n$ tree\n<span class="token builtin class-name">.</span>\n└── 0hi<span class="token punctuation">)</span>_mB.wf.txt\n</code></pre><div class="line-numbers"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><hr><h2 id="file-generation" tabindex="-1"><a class="header-anchor" href="#file-generation" aria-hidden="true">#</a> File generation</h2><h3 id="number-of-files" tabindex="-1"><a class="header-anchor" href="#number-of-files" aria-hidden="true">#</a> Number of files</h3><p>Use <code>-n</code> to specify how many files to create.</p><div class="language-bash ext-sh line-numbers-mode"><pre class="language-bash"><code>$ dammy.sh -n <span class="token number">3</span>\n$ tree\n<span class="token builtin class-name">.</span>\n├── <span class="token variable">$qxT2</span>+_&#39;uW.txt\n├── pdK:gXwu.Q.txt\n└── tl4NUT<span class="token punctuation">(</span>q7b.txt\n</code></pre><div class="line-numbers"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><h3 id="file-extension" tabindex="-1"><a class="header-anchor" href="#file-extension" aria-hidden="true">#</a> File extension</h3><p>Use <code>-e</code> to set the file extension. Default is <code>txt</code>.</p><div class="language-bash ext-sh line-numbers-mode"><pre class="language-bash"><code>$ dammy.sh -n <span class="token number">3</span> -e csv\n$ tree\n<span class="token builtin class-name">.</span>\n├── <span class="token punctuation">;</span>mSu179.QE.csv\n├── JGElYbT3d<span class="token punctuation">\\</span>.csv\n└── tyP+<span class="token punctuation">\\</span>woXGQ.csv\n</code></pre><div class="line-numbers"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><hr><h2 id="image-file-generation" tabindex="-1"><a class="header-anchor" href="#image-file-generation" aria-hidden="true">#</a> Image file generation</h2><p>When you specify an image format with <code>-e</code>, dammy generates <strong>actual image files</strong> using ImageMagick instead of empty files. Each image is a gray canvas with the dimensions printed at the center — useful as placeholder images in web development and UI mockups.</p><p>Supported formats: <code>jpg</code> <code>jpeg</code> <code>png</code> <code>gif</code> <code>bmp</code> <code>tiff</code> <code>webp</code></p><p>The filename is set to the image dimensions (e.g. <code>100x100.jpg</code>). When generating multiple files, a sequential number is appended.</p><div class="language-bash ext-sh line-numbers-mode"><pre class="language-bash"><code>$ dammy.sh -n <span class="token number">3</span> -e jpg\n$ tree\n<span class="token builtin class-name">.</span>\n├── 100x100_1.jpg\n├── 100x100_2.jpg\n└── 100x100_3.jpg\n</code></pre><div class="line-numbers"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><h3 id="image-size" tabindex="-1"><a class="header-anchor" href="#image-size" aria-hidden="true">#</a> Image size</h3><p>Use <code>-s</code> to specify the image dimensions in <code>WxH</code> format. Default is <code>100x100</code>.</p><div class="language-bash ext-sh line-numbers-mode"><pre class="language-bash"><code>$ dammy.sh -n <span class="token number">3</span> -e png -s 320x240\n$ tree\n<span class="token builtin class-name">.</span>\n├── 320x240_1.png\n├── 320x240_2.png\n└── 320x240_3.png\n</code></pre><div class="line-numbers"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><div class="custom-container tip"><p class="custom-container-title">TIP</p><p>ImageMagick must be installed to use image generation. If it is not installed, dammy will show an error with installation instructions.</p></div><hr><h2 id="file-name-options" tabindex="-1"><a class="header-anchor" href="#file-name-options" aria-hidden="true">#</a> File name options</h2><h3 id="no-symbols" tabindex="-1"><a class="header-anchor" href="#no-symbols" aria-hidden="true">#</a> No symbols</h3><p><code>--no-symbol</code> generates file names using only alphanumeric characters.</p><div class="language-bash ext-sh line-numbers-mode"><pre class="language-bash"><code>$ dammy.sh -n <span class="token number">3</span> --no-symbol\n$ tree\n<span class="token builtin class-name">.</span>\n├── Q5aocxH9uI.txt\n├── TfxZIic3Rg.txt\n└── ucmiz657Ae.txt\n</code></pre><div class="line-numbers"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><h3 id="include-whitespace" tabindex="-1"><a class="header-anchor" href="#include-whitespace" aria-hidden="true">#</a> Include whitespace</h3><p><code>--with-whitespace</code> includes spaces in file names. Useful for testing how your application handles paths with spaces.</p><div class="language-bash ext-sh line-numbers-mode"><pre class="language-bash"><code>$ dammy.sh -n <span class="token number">3</span> --with-whitespace\n$ tree\n<span class="token builtin class-name">.</span>\n├── J L $ A <span class="token punctuation">(</span> .txt\n├── T w N V c .txt\n└── V n <span class="token number">0</span> <span class="token punctuation">)</span> Z .txt\n</code></pre><div class="line-numbers"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><h3 id="include-2-byte-characters" tabindex="-1"><a class="header-anchor" href="#include-2-byte-characters" aria-hidden="true">#</a> Include 2-byte characters</h3><p><code>--zenkaku</code> includes Japanese (2-byte) characters in file names. Useful for testing multibyte filename handling.</p><div class="language-bash ext-sh line-numbers-mode"><pre class="language-bash"><code>$ dammy.sh -n <span class="token number">3</span> --zenkaku\n$ tree\n<span class="token builtin class-name">.</span>\n├── 3aしにmう.txt\n├── Xたれ9かi.txt\n└── ゆBwはZ1.txt\n</code></pre><div class="line-numbers"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><hr><h2 id="directory-generation" tabindex="-1"><a class="header-anchor" href="#directory-generation" aria-hidden="true">#</a> Directory generation</h2><p>Pass a path as an argument to create the directory and place files inside it. Non-existent intermediate directories are created automatically.</p><div class="language-bash ext-sh line-numbers-mode"><pre class="language-bash"><code>$ dammy.sh hoge/foo/bar -n <span class="token number">2</span>\n$ tree\n<span class="token builtin class-name">.</span>\n└── hoge\n    └── foo\n        └── bar\n            ├── :w9a@DmC~N.txt\n            └── Ab3Kp<span class="token operator">!</span>mQvX.txt\n</code></pre><div class="line-numbers"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br></div></div><h3 id="multiple-directories" tabindex="-1"><a class="header-anchor" href="#multiple-directories" aria-hidden="true">#</a> Multiple directories</h3><p>Pass multiple paths to create files in several directories at once.</p><div class="language-bash ext-sh line-numbers-mode"><pre class="language-bash"><code>$ dammy.sh hoge foo bar\n$ tree\n<span class="token builtin class-name">.</span>\n├── bar\n│   └── J<span class="token punctuation">(</span>q<span class="token operator">=</span>E.@Ma0.txt\n├── foo\n│   └── x<span class="token operator">&amp;</span>bY,2s<span class="token punctuation">)</span>qg.txt\n└── hoge\n    └── 9BcTRkOgLw.txt\n</code></pre><div class="line-numbers"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br></div></div><h3 id="create-files-in-every-intermediate-directory" tabindex="-1"><a class="header-anchor" href="#create-files-in-every-intermediate-directory" aria-hidden="true">#</a> Create files in every intermediate directory</h3><p><code>--each</code> places files in every directory in the path, not just the deepest one.</p><div class="language-bash ext-sh line-numbers-mode"><pre class="language-bash"><code>$ dammy.sh hoge/foo/bar --each\n$ tree\n<span class="token builtin class-name">.</span>\n└── hoge\n    ├── <span class="token operator">&amp;</span>dGzWh<span class="token operator">!</span>F2f.txt\n    ├── foo\n    │   ├── Pq7mNzKsYo.txt\n    │   └── bar\n    │       └── %<span class="token punctuation">\\</span>&#39;fRw2z,h.txt\n    └── yLv*lTz<span class="token punctuation">\\</span>BG.txt\n</code></pre><div class="line-numbers"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br></div></div><hr><h2 id="shell-brace-expansion" tabindex="-1"><a class="header-anchor" href="#shell-brace-expansion" aria-hidden="true">#</a> Shell brace expansion</h2><p>dammy works naturally with shell brace expansion.</p><div class="language-bash ext-sh line-numbers-mode"><pre class="language-bash"><code>$ dammy.sh hoge/<span class="token punctuation">{</span>foo,bar<span class="token punctuation">}</span>/piyo -n <span class="token number">2</span>\n$ tree\n<span class="token builtin class-name">.</span>\n└── hoge\n    ├── bar\n    │   └── piyo\n    │       ├── ey<span class="token punctuation">\\</span>%lAFx2V.txt\n    │       └── 9k~MYXwoH<span class="token operator">!</span>.txt\n    └── foo\n        └── piyo\n            ├── Kd4pRmTzWq.txt\n            └── Vu8nXjBsLe.txt\n</code></pre><div class="line-numbers"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br></div></div><hr><h2 id="cold-run" tabindex="-1"><a class="header-anchor" href="#cold-run" aria-hidden="true">#</a> Cold run</h2><p><code>--cold-run</code> shows you the directory tree that <em>would</em> be created, without actually creating anything. Use it to verify the output before committing.</p><div class="language-bash ext-sh line-numbers-mode"><pre class="language-bash"><code>$ dammy.sh hoge/<span class="token punctuation">{</span>foo,bar<span class="token punctuation">}</span>/piyo --each -n <span class="token number">3</span> --cold-run\n<span class="token builtin class-name">.</span>\n└── hoge\n    ├── +_60SaTUoh.txt\n    ├── COrDP*WZ2X.txt\n    ├── S:0myGYPX<span class="token punctuation">(</span>.txt\n    ├── bar\n    │   ├── <span class="token number">9</span><span class="token punctuation">\\</span><span class="token punctuation">\\</span><span class="token operator">=</span>o7y5<span class="token punctuation">)</span>:e.txt\n    │   ├── CJso1@z<span class="token punctuation">)</span>ZD.txt\n    │   ├── Lg7<span class="token punctuation">)</span>ruOtbH.txt\n    │   └── piyo\n    │       ├── <span class="token operator">&amp;</span>:u-BmLSa3.txt\n    │       ├── _j,eoIl1nZ.txt\n    │       └── gd,5xhU<span class="token punctuation">(</span><span class="token operator">!</span>o.txt\n    ├── d6g.pTULy9.txt\n    ├── foo\n    │   ├── 0A<span class="token punctuation">)</span>T<span class="token operator">=</span>qK@Uh.txt\n    │   ├── R8*.40<span class="token punctuation">;</span>B_u.txt\n    │   ├── kd$%K,<span class="token punctuation">)</span>24l.txt\n    │   └── piyo\n    │       ├── <span class="token punctuation">(</span><span class="token punctuation">\\</span><span class="token punctuation">\\</span>3p0ibK1S.txt\n    │       ├── B0dGSQxzmv.txt\n    │       └── ~L3<span class="token punctuation">\\</span><span class="token punctuation">\\</span>SGc<span class="token variable">$X9</span>.txt\n    ├── n<span class="token punctuation">(</span>x5@_alTr.txt\n    └── nCH:qsx<span class="token punctuation">\\</span><span class="token punctuation">\\</span><span class="token punctuation">(</span>f.txt\n\n<span class="token number">5</span> directories, <span class="token number">18</span> files\n</code></pre><div class="line-numbers"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br><span class="line-number">17</span><br><span class="line-number">18</span><br><span class="line-number">19</span><br><span class="line-number">20</span><br><span class="line-number">21</span><br><span class="line-number">22</span><br><span class="line-number">23</span><br><span class="line-number">24</span><br><span class="line-number">25</span><br><span class="line-number">26</span><br><span class="line-number">27</span><br></div></div><p>Once you are happy with the preview, remove <code>--cold-run</code> and run the same command for real.</p><hr><h2 id="options-reference" tabindex="-1"><a class="header-anchor" href="#options-reference" aria-hidden="true">#</a> Options reference</h2><table><thead><tr><th>Option</th><th>Description</th></tr></thead><tbody><tr><td><code>-h</code>, <code>--help</code></td><td>Show help and exit</td></tr><tr><td><code>-v</code>, <code>--version</code></td><td>Show version and exit</td></tr><tr><td><code>-n</code>, <code>--number</code></td><td>Number of files to create (default: 1)</td></tr><tr><td><code>-e</code>, <code>--ext</code></td><td>File extension (default: <code>txt</code>)</td></tr><tr><td><code>-s</code>, <code>--size</code></td><td>Image size in <code>WxH</code> format (default: <code>100x100</code>). Image formats only.</td></tr><tr><td><code>-w</code>, <code>--with-whitespace</code></td><td>Include spaces in file names</td></tr><tr><td><code>-z</code>, <code>--zenkaku</code></td><td>Include 2-byte (Japanese) characters in file names</td></tr><tr><td><code>--no-symbol</code></td><td>Exclude symbol characters from file names</td></tr><tr><td><code>--each</code></td><td>Create files in every intermediate directory</td></tr><tr><td><code>--cold-run</code></td><td>Preview output without creating files</td></tr><tr><td><code>--verbose</code></td><td>Print debug information</td></tr></tbody></table>',55),t={},l=(0,s(3744).Z)(t,[["render",function(n,e){return a}]])},3744:(n,e)=>{e.Z=(n,e)=>{const s=n.__vccOpts||n;for(const[n,a]of e)s[n]=a;return s}}}]);